window.AAQ_ASSIGN = {"unit": 4, "title": "Health, Policy and Wellbeing", "aims": [{"aim": "A", "title": "Understand the influence of social policy on public health"}, {"aim": "B", "title": "Examine the factors affecting public health policy and the impact of addressing these factors to improve public health"}, {"aim": "C", "title": "Examine the impact of social policy as a driver to improve outcomes in public health"}], "criteria": [{"code": "A.P1", "aims": "A", "grade": "P", "n": 1, "text": "Compare differences between the implementation of public health aims of the post- 1948 public health policy and current practice."}, {"code": "A.P2", "aims": "A", "grade": "P", "n": 2, "text": "Discuss the influence of one national or one international group on current public health policy."}, {"code": "A.M1", "aims": "A", "grade": "M", "n": 1, "text": "Assess the benefits to individuals of current ways of implementing one post- 1948 public health aim."}, {"code": "A.M2", "aims": "A", "grade": "M", "n": 2, "text": "Analyse the influence of one national or international group on current public health policy."}, {"code": "A.D1", "aims": "A", "grade": "D", "n": 1, "text": "Evaluate the influence of post-1948 public health aims, and one national or international group, on current public health policy."}, {"code": "B.P3", "aims": "B", "grade": "P", "n": 3, "text": "Explain how two different factors affecting the development and implementation of public health policy, can impact a specific group."}, {"code": "B.P4", "aims": "B", "grade": "P", "n": 4, "text": "Discuss the effects of monitoring the effectiveness of public health policy, on the health and wellbeing of a specific group."}, {"code": "B.M3", "aims": "B", "grade": "M", "n": 3, "text": "Assess the benefits of public health policy to the same group, with reference to one method used to measure effectiveness of the policy"}, {"code": "B.D2", "aims": "B", "grade": "D", "n": 2, "text": "Evaluate the effectiveness of public health policy for the same group, with reference to one method of measurement used."}, {"code": "C.P5", "aims": "C", "grade": "P", "n": 5, "text": "Explain the potential impact on users of services when health and social care organisations work as partners to provide care."}, {"code": "C.P6", "aims": "C", "grade": "P", "n": 6, "text": "Explain the significance of partnership approaches in promoting social policy change."}, {"code": "C.M4", "aims": "C", "grade": "M", "n": 4, "text": "Assess the importance of collaborative working between different health and social care organisations in promoting social policy change."}, {"code": "C.D4", "aims": "C", "grade": "D", "n": 4, "text": "Analyse the ways in which health and social care organisations work collaboratively to promote social policy change."}], "guidance": [{"aims": "A", "paras": ["Students should base all work for Learning Aim A on the same public health policy. Students will select one national or international group on which to base their work, selected from the list provided in the assignment brief. For distinction standard, students’ evidence should lead to a methodical and concise conclusion that considers how successful post-1948 public health aims have been in addressing health and social care issues. Strengths and weaknesses of the aims should be considered, and an overall judgement reached, that is underpinned with sound reasoning. Students will then focus in more detail on a selected influencing group (either national or international), taking a non-biased approach, considering strengths and weaknesses in detail and discussing alternative approaches where relevant; for example, how could the selected group have approached the health issues to achieve a more positive conclusion, giving examples of alternative approaches linked to areas of weakness. The selected group must be currently active, and evidence of research must be included. For merit standard, students must assess the impact of one post-1948 public health aims, on current practice, and evidence must clearly show how public health provision developed post-1948. Students will present a detailed analysis that considers in detail how one national or international group, has influenced one public health policy. Students should include graphical data to illustrate the points made. Data should be accurate, current, relevant and explained; sources consulted should be referenced within the evidence presented. For pass standard, students will identify the relevant differences between the main aims of post-1948 public health policy and current public health policy. They will compare the similarities, differences, advantages and disadvantages of each set of aims. Examples should be included, to illustrate points made. Students could base their work on either health or social care.", "Students will discuss different aspects of historic and current public health aims and the extent to which they are important. Examples should be included to illustrate points, together with graphical data, which is accurate, current, relevant and explained. Balanced discussion considering alternative views is required to meet the pass criterion. Students will also discuss the influence of either one national or international group on the same public health policy. The group must be operating currently and can be linked to either health or social care."]}, {"aims": "B", "paras": ["Students should base work for Learning Aim B on a specific group, from the options provided in the assignment brief. For distinction standard, students will give a clear and logical analysis presented as the result of a methodical and detailed examination of the impact of public health policy on factors affecting a selected group of individuals. Students must examine how effective public health policy is, in improving the health of a specific group of individuals. Students must break down the policy into its different characteristics, to examine how it effectively meets the diverse need of the specific group selected. Students must use secondary sources of evidence to reach valid and supported conclusions for the effectiveness of the public health policy for at least three selected factors, illustrated by two examples of benefits for each. Within this, students must refer to one method of measuring effectiveness of public health policy to demonstrate their understanding of the links between public health policy, its development and implementation, and the effects it has on outcomes for individuals. For merit standard, students must consider, in detail, the benefits of public health policy for a selected group of individuals. Students will have considered two factors and the impact of these on the development and implementation of public health policy and must now make judgements on how this policy affects the outcomes of the selected group; with reference to one aspect of measurement used to assess effectiveness. Students must use secondary sources of evidence to examine how accurate the data produced is in highlighting issues, and how these issues are dealt with, giving two examples. Each factor must be defined, and students will assess how they affect the selected group. The work must include a reasoned judgement that considers the benefit of public health policy in relation to two factors, and the contributions made towards monitoring the impact of the policy using a selected method of measurement. For pass standard, students will provide a detailed explanation of the different aspects of the selected public health policy and provide a balanced examination of its purpose. Student’s evidence should also include a discussion of how monitoring the selected public health policy can impact the health and wellbeing of their chosen specific group. The discussion should relate to two different factors, giving two examples of potential effects on individuals, for each factor."]}, {"aims": "C", "paras": ["For distinction, students will provide a detailed examination of the ways in which two different organisations work in partnership to promote social policy change. Students must break down information to interpret key relationships including the advantages and disadvantages of these working practices, providing a detailed examination, including examples, for the statements made. Students will explore the key principles of working in partnerships, including collaborative working, linking these to working practices within two health and social care organisations. Students must articulate arguments, using secondary sources of evidence to validate their judgements, considering the strengths or weaknesses, advantages or disadvantages of working practices and at least one alternative working practice that could be taken, to promote social policy change. For merit standard, students will present the outcome of a methodical and detailed assessment that considers potential impact of two organisations working collaboratively to promote social policy change, and the extent to which each key principle of collaborative working is important to the delivery of care and support within each organisation. Students will use evidence obtained from valid secondary sources to make reasoned judgements on the partnership approaches of two organisations as a mechanism to improve outcomes and relate this to social policy and the impact on public health. For pass standard, students will explain in detail, the potential impact of organisations working as partners on users of services. They will explain different aspects of partnership approaches including the key principles of collaborative working and consider how they interrelate in terms of contributing to the meeting of the needs of individuals, within each of two health and social care organisations."]}]};
